    'Jei paskyra laukia patvirtinimo, naują nuorodą išsiuntėme el. paštu.' => 'Если аккаунт ожидает подтверждения, мы отправили новую ссылку по эл. почте.',
    'Jei toks el. paštas registruotas, išsiuntėme nuorodą slaptažodžiui atkurti.' => 'Если такая эл. почта зарегистрирована, мы отправили ссылку для восстановления пароля.',
    'Jei tėvai dar neturi paskyros - palikite tuščią. Kai užsiregistruos, susiekite nario puslapyje, kad tas pats vaikas nebūtų sukurtas du kartus.' => 'Если у родителей ещё нет аккаунта - оставьте пустым. Когда они зарегистрируются, свяжите их на странице участника, чтобы один ребёнок не был создан дважды.',
