    'Junior pažymi kito diržo programos punktus „Moku“ - Denis tvirtina, skiriami XP (jei programa surašyta).' => 'Junior отмечает пункты программы следующего пояса «Умею» - Денис подтверждает, начисляются XP (если программа составлена).',
    'Juodraštis išsaugotas.' => 'Черновик сохранён.',
    'Juodraščiai ir suplanuotos - mato tik treneriai' => 'Черновики и запланированные - видят только тренеры',
    'Juosta su tekstu' => 'Полоса с текстом',
    'Ją tėvai (ar suaugęs narys) pasirašo elektroniniu parašu per Edufi. Sutartyje yra nario vardas, pavardė ir gimimo data, tėvų (globėjų) vardas, pavardė, telefonas ir el. paštas.
     Šiuo el. paštu siunčiame informaciją apie treniruotes, renginius ir tvarkaraščio pakeitimus.
     Klubui taip pat pateikiate gydytojo pažymą, kad narys gali sportuoti, į svetainę ji nekeliama. Pagrindas - narystės sutartis.' => 'Родители (или взрослый участник) подписывают его электронной подписью через Edufi. В договоре указаны имя, фамилия и дата рождения участника, имя, фамилия, телефон и эл. почта родителей (опекунов). На эту эл. почту мы отправляем информацию о тренировках, мероприятиях и изменениях расписания. Клубу вы также предоставляете справку врача, что участник может заниматься спортом; на сайт она не загружается. Основание - договор о членстве.',
    'Jėga, forma ir aiški galva po darbo dienos' => 'Сила, форма и ясная голова после рабочего дня',
    'Jūs' => 'Вы',
