    'Klausimas' => 'Вопрос',
    'Klausimas Deniui prie naujausios naujienos ir renginio, žinutė pokalbyje - atsakyti, paviešinti.' => 'Вопрос Денису к последней новости и мероприятию, сообщение в чате - ответить, опубликовать.',
