    'Kokį bloką pridėti?' => 'Какой блок добавить?',
    'Kol kas varžybas kurkite kaip įprastą renginį (Renginiai → „+ Naujas renginys“, tipas „Varžybos“), o rezultatus įrašykite renginio rezultatuose.' => 'Пока создавайте соревнования как обычное мероприятие (Мероприятия → «+ Новое мероприятие», тип «Соревнования»), а результаты вносите в результаты мероприятия.',
