          Jei narys tik nebetreniruoja - geriau „Būsena: Neaktyvus“ (privatumo politikoje: ištriname praėjus 1 m.).' => 'Участник удаляется навсегда вместе с посещаемостью, баллами, заметками и сообщениями. Аккаунт родителей или самого участника, в котором не останется участников, тоже удаляется. Если участник просто больше не тренируется - лучше «Статус: Неактивный» (в политике конфиденциальности: удаляем через 1 год).',
