     Ją naudojame tik tam, kad susisiektume ir suderintume treniruotę. Pagrindas - jūsų prašymas prieš sudarant sutartį.' => 'Мы собираем имя, фамилию, эл. почту, телефон, место тренировок, год рождения и ваше сообщение. Запрос приходит клубу по эл. почте. Мы используем его только для того, чтобы связаться и согласовать тренировку. Основание - ваш запрос до заключения договора.',
