    'Svarbu' => 'Важно',
    'Sveikas (-a),' => 'Привет,',
    'Sveiki,' => 'Здравствуйте,',
    'Sveikiname!' => 'Поздравляем!',
    'Svetainė veikia per šifruotą HTTPS ryšį. Slaptažodžiai saugomi tik užšifruoti. Narių duomenis mato tik prisijungę treneriai,
     jų paskyroms galima įjungti prisijungimą su papildomu kodu el. paštu. Kasdien daroma atsarginė duomenų bazės kopija.' => 'Сайт работает через зашифрованное соединение HTTPS. Пароли хранятся только в зашифрованном виде. Данные участников видят только вошедшие тренеры, для их аккаунтов можно включить вход с дополнительным кодом по эл. почте. Ежедневно делается резервная копия базы данных.',
    'Svetainėje (Renginiai ir Mano paskyra) - visada' => 'На сайте (Мероприятия и Мой кабинет) - всегда',
    'Svetainės versija' => 'Версия сайта',
    'Svetainės versija (rodoma tik testuojant)' => 'Версия сайта (показывается только при тестировании)',
    'Svetainės šriftai įkeliami iš „Google Fonts“, o vaizdo įrašai rodomi per „YouTube“ privatumo režimu (youtube-nocookie.com).
     Įkeliant šį turinį jūsų naršyklė susisiekia su „Google“ serveriais ir perduoda jūsų IP adresą.' => 'Шрифты сайта загружаются из «Google Fonts», а видео показываются через «YouTube» в режиме конфиденциальности (youtube-nocookie.com). При загрузке этого содержимого ваш браузер связывается с серверами Google и передаёт ваш IP-адрес.',
    'Svetainę ir el. paštą talpina domenai.lt (Lietuva). Narystės sutartys pasirašomos per Edufi. Jie duomenų nenaudoja savo tikslais.
        SMS žinučių kol kas nesiunčiame - pasirinkus SMS teikėją, jis bus nurodytas čia.' => 'Сайт и эл. почту размещает domenai.lt (Литва). Договоры о членстве подписываются через Edufi. Они не используют данные в своих целях. SMS мы пока не отправляем - когда выберем SMS-провайдера, он будет указан здесь.',
    'Sąskaita' => 'Счёт',
    'Tai jūsų dabartinis el. paštas.' => 'Это ваша текущая эл. почта.',
    'Tai užduotis: narys paskyroje matys mygtuką „Atlikau“ ir pažymės, kai atliks' => 'Это задание: участник увидит в аккаунте кнопку «Сделал» и отметит, когда выполнит',
    'Taip pat išsiuntėme laišką tavo tėvams: kai jie patvirtins, paskyrą peržiūrės treneris.' => 'Мы также отправили письмо твоим родителям: когда они подтвердят, тренер проверит аккаунт.',
    'Taip pat išsiųsti el. laišką (vaikui / tėvams)' => 'Также отправить письмо (ребёнку / родителям)',
