        Pakeista vertė galioja tik naujiems skyrimams - anksčiau skirti taškai nesikeičia.' => 'Баллы и XP - одно и то же: из баллов сезона считается рейтинг, из всех когда-либо набранных - уровень аккаунта участника. Изменённое значение действует только для новых начислений - ранее начисленные баллы не меняются.',
