    'Treniruotės suaugusiems, pritaikytos tiek pradedantiesiems, tiek turintiems patirties. Realus fizinis krūvis kartu su savigynos pagrindais.' => 'Тренировки для взрослых, подходят как новичкам, так и опытным. Реальная физическая нагрузка вместе с основами самообороны.',
