    'Trumpai' => 'Кратко',
    'Trumpi pranešimai telefonu, pvz. „Šiandien treniruotės nebus“. Vaikams SMS gauna tėvai, suaugusieji - patys. Numeriai imami iš paskyrų.' => 'Короткие сообщения на телефон, напр. «Сегодня тренировки не будет». За детей SMS получают родители, взрослые - сами. Номера берутся из аккаунтов.',
    'Trūksta duomenų bazės lentelės - importuokite db/018_zinutes.sql.' => 'Не хватает таблицы базы данных - импортируйте db/018_zinutes.sql.',
