     Tėvai gali užregistruoti vaiką patys. Savo paskyroje jie mato vaiko informaciją, trenerio pastabas ir žinutes.' => 'Аккаунт ребёнка до 14 лет активируется только после получения согласия родителей или опекунов по эл. почте. В Литве ребёнок может самостоятельно дать согласие с 14 лет. Родители могут зарегистрировать ребёнка сами. В своём аккаунте они видят информацию о ребёнке, заметки тренера и сообщения.',
