    'Test varžybos' => 'Тестовые соревнования',
    'Varžybos su Karateka nariais ir kitų klubų išgalvotais dalyviais, kategorijomis ir dalimi įvykusių kovų - kad greitai pamatytumėte lenteles, tvarkaraštį, rezultatus ir LTKF puslapį. Į narių taškus neperkeliamos.' => 'Соревнование с членами Karateka, вымышленными спортсменами других клубов, категориями и частью проведённых боёв - чтобы быстро увидеть сетки, расписание, результаты и страницу LTKF. В очки членов не переносится.',
