    'nuotraukos?' => 'фото?',
    'Tuščios eilutės nesiunčiamos. Vaikams iki 18 m. - būtinas vieno iš tėvų telefonas.' => 'Пустые строки не отправляются. Для детей до 18 лет нужен телефон одного из родителей.',
    'Duomenys naudojami tik šioms varžyboms organizuoti: kategorijos, lentelės, tvarkaraštis, rezultatai. Telefonai - tik susisiekti dėl varžybų; jie ištrinami praėjus mėnesiui po varžybų. Varžybų lentelėse ir rezultatuose rodomas vardas, pavardė ir klubas; vaikų ir jaunių iki 18 m. - vardas ir pavardės pirmoji raidė.' => 'Данные используются только для организации этих соревнований: категории, сетки, расписание, результаты. Телефоны - только для связи по поводу соревнований; они удаляются через месяц после соревнований. В сетках и результатах показываются имя, фамилия и клуб; для детей и юниоров до 18 лет - имя и первая буква фамилии.',
    'Duomenų valdytojas - VšĮ Karate Ateitis.' => 'Контролёр данных - VšĮ Karate Ateitis.',
    'Turite teisę susipažinti su savo duomenimis, juos ištaisyti ar paprašyti ištrinti:' => 'Вы имеете право ознакомиться со своими данными, исправить их или попросить удалить:',
    'Varžybų metu fotografuojama ir filmuojama. Dalyvių, kurie nesutinka, nuotraukų ir video organizatorius neskelbia.' => 'Во время соревнований ведётся фото- и видеосъёмка. Фото и видео участников, которые не согласны, организатор не публикует.',
    'Sutinku, kad organizatoriai naudotų pateiktus duomenis varžybų organizavimui.' => 'Я согласен(-на), что организаторы используют предоставленные данные для организации соревнований.',
    'privatumo politika' => 'политикой конфиденциальности',
    '{name}: pasirinkite, ar sutinka būti fotografuojamas ir filmuojamas.' => '{name}: выберите, согласен(-на) ли на фото- и видеосъёмку.',
    '{name}: patikrinkite telefono numerį.' => '{name}: проверьте номер телефона.',
    '{name}: įrašykite vieno iš tėvų telefono numerį.' => '{name}: впишите телефон одного из родителей.',
