    // v1.28
    'Bandymo nuoroda sukurta - nukopijuokite ir nusiųskite.' => 'Ссылка для пробы создана - скопируйте и отправьте.',
    'Bandymo nuoroda išjungta - su ja nebeprisijungs.' => 'Ссылка для пробы отключена - по ней больше не войти.',
    'Bandymo varžybos sukurtos: išgalvoti dalyviai, kategorijos sudarytos, dalis kovų jau įvyko.' => 'Пробные соревнования созданы: вымышленные участники, категории составлены, часть боёв уже прошла.',
    '👋 Sveiki,' => '👋 Здравствуйте,',
    'Tai Budo varžybų sistemos bandymas: galite daryti viską, ką daro sekretoriatas ir organizatorius - kurti varžybas, dalyvius, kategorijas, vesti kovas, siųsti apdovanojimams.' => 'Это проба системы соревнований Budo: можно делать всё, что делают секретариат и организатор - создавать соревнования, участников, категории, вести бои, отправлять на награждение.',
    'Pradėkite nuo „🎲 Sukurti test varžybas“ - bus išgalvoti dalyviai ir dalis kovų. Pastebėjimus rašykite per' => 'Начните с «🎲 Создать тестовые соревнования» - появятся вымышленные участники и часть боёв. Замечания пишите через',
    '(apačioje kairėje) - galima įklijuoti ekrano nuotrauką (Ctrl+V).' => '(внизу слева) - можно вставить снимок экрана (Ctrl+V).',
    '👀 Duoti išbandyti (be paskyros)' => '👀 Дать попробовать (без учётной записи)',
    '- draugui ar kito klubo sekretoriatui' => '- другу или секретариату другого клуба',
    'Su šia nuoroda žmogus įrašo savo vardą ir gali daryti viską, ką daro adminas, bet tik bandymo varžybose: tikrų klubo narių ir jų duomenų nemato, karateka.lt valdymo neatidaro. Atsiliepimus (💡) matysite Valdymas → Atsiliepimai.' => 'По этой ссылке человек вводит своё имя и может делать всё, что админ, но только в пробных соревнованиях: настоящих членов клуба и их данных не видит, управление karateka.lt не открывает. Отзывы (💡) увидите в Управление → Отзывы.',
    'Bandymo nuoroda' => 'Ссылка для пробы',
    'Sukurti naują nuorodą? Sena nebeveiks.' => 'Создать новую ссылку? Старая перестанет работать.',
