    'Rodyti žemėlapyje' => 'Показать на карте',
    'Paspaudę vardą atidarysite nario puslapį.' => 'Нажмите на имя, чтобы открыть страницу участника.',
    '„+ Taškai“ prie vardo - skirti taškų iškart.' => '«+XP» рядом с именем — начислить XP сразу.',
