    'Nuoroda federacijos nariams: atsidarę jie mato LTKF svetainę ir gali palikti atsiliepimus (💡, galima įklijuoti nuotrauką). Nuorodos į karateka.lt nemato - ją mato tik adminas.' => 'Ссылка для членов федерации: они видят сайт LTKF и могут оставлять отзывы (💡, можно вставить снимок экрана). Ссылку на karateka.lt они не видят — её видит только администратор.',
