    'Atidaryti LTKF svetainę →' => 'Открыть сайт LTKF →',
    'Nuoroda jau panaudota arba pasibaigė. Paprašykite trenerio atsiųsti naują.' => 'Ссылка уже использована или истекла. Попросите тренера прислать новую.',
    'Šis narys jau turi savo paskyrą. Jei esate tėvai - pasirinkite „Aš - tėvai ar globėjai“.' => 'У этого участника уже есть своя учётная запись. Если вы родитель — выберите «Я — родитель или опекун».',
    'Narys pridėtas prie jūsų paskyros:' => 'Участник добавлен в вашу учётную запись:',
    'Šis el. paštas jau turi paskyrą - prisijunkite ir atidarykite nuorodą dar kartą.' => 'Для этого e-mail уже есть учётная запись — войдите и откройте ссылку ещё раз.',
    'Paskyra sukurta! Narys jau susietas su jūsų paskyra.' => 'Учётная запись создана! Участник уже привязан к вашей учётной записи.',
    'Kvietimas į karateka.lt' => 'Приглашение на karateka.lt',
    'Treneris pridėjo šį narį į klubo sistemą. Susikurkite prisijungimą - matysite tvarkaraštį, renginius, aktyvumo taškus ir klubo žaidimą.' => 'Тренер добавил этого участника в систему клуба. Создайте вход — вы увидите расписание, мероприятия, XP и игру клуба.',
    'Kas jūs?' => 'Кто вы?',
