    'pakvietimo nuorodą rasite žemiau - nusiųskite ją žinute' => 'ссылка-приглашение ниже — отправьте её сообщением',
    'Užtenka vardo, pavardės ir gimimo metų arba grupės. Visa kita galima papildyti vėliau.' => 'Достаточно имени, фамилии и года рождения или группы. Всё остальное можно добавить позже.',
    'pvz. 2016' => 'напр. 2016',
