    '+ Tiksli gimimo data (nebūtina)' => '+ Точная дата рождения (необязательно)',
    'El. paštas pakvietimui' => 'E-mail для приглашения',
    'nebūtina - tėvų ar paties nario' => 'необязательно — родителя или самого участника',
    'Jei paskyra su šiuo el. paštu jau yra - susiesime iš karto. Jei nėra - išsiųsime pakvietimą susikurti prisijungimą. Be el. pašto gausite nuorodą, kurią galima nusiųsti žinute: užsiregistravęs per ją žmogus bus susietas su šiuo nariu.' => 'Если учётная запись с этим e-mail уже есть — привяжем сразу. Если нет — отправим приглашение создать вход. Без e-mail вы получите ссылку, которую можно отправить сообщением: зарегистрировавшийся по ней будет привязан к этому участнику.',
    'Pakvietimas išsiųstas:' => 'Приглашение отправлено:',
