    'žinomi tik metai - patikslinkite' => 'известен только год — уточните',
    'metai apytiksliai pagal grupę - patikslinkite' => 'год примерно по группе — уточните',
    '✉️ Pakviesti susikurti prisijungimą' => '✉️ Пригласить создать вход',
    'Nusiųskite šią nuorodą žinute (Messenger, SMS). Užsiregistravęs per ją žmogus bus susietas su šiuo nariu.' => 'Отправьте эту ссылку сообщением (Messenger, SMS). Зарегистрировавшийся по ней будет привязан к этому участнику.',
    'nebūtina - be jo gausite nuorodą nukopijuoti' => 'необязательно — без него получите ссылку для копирования',
    'Siųsti el. paštu / nauja nuoroda' => 'Отправить по e-mail / новая ссылка',
