    'Registras' => 'Реестр',
    'Visi laikę egzaminus. Kiekvienas žmogus turi nuolatinį numerį (pvz. 26.11.15-1): data - pirmo egzamino, po brūkšnio - tos dienos eilė. Numeris niekada nesikartoja.' => 'Все сдававшие экзамены. У каждого постоянный номер (напр. 26.11.15-1): дата первого экзамена, после дефиса — порядковый номер того дня. Номер никогда не повторяется.',
