    'Kaina už treniruotę (€)' => 'Цена за тренировку (€)',
    'Daugiausia per mėnesį (€)' => 'Максимум в месяц (€)',
    'Suma kaupiasi pagal pažymėtą lankomumą („✓ Buvo“) ir matoma „Treniruotė“ puslapyje prie kiekvieno nario.' => 'Сумма накапливается по отмеченной посещаемости («✓ Был») и видна на странице «Тренировка» у каждого участника.',
    '📋 Egzaminavimas' => '📋 Экзамены',
    'Egzaminavimas' => 'Экзамены',
    'Visi egzaminai vienoje vietoje: protokolas, registracija per nuorodą ir rezultatai.' => 'Все экзамены в одном месте: протокол, регистрация по ссылке и результаты.',
    '+ Naujas egzaminas' => '+ Новый экзамен',
