    'Žmonės be paskyros (pvz. kitų klubų) užsiregistruoja patys: vardas, pavardė, el. paštas. Jie iškart atsiranda šiame protokole.' => 'Люди без аккаунта (например, из других клубов) регистрируются сами: имя, фамилия, эл. почта. Они сразу появляются в этом протоколе.',
    'Sukurti registracijos nuorodą' => 'Создать ссылку для регистрации',
    'Nusiųskite nuorodą bet kam (Messenger, el. paštu). Užsiregistravę iškart atsiranda protokole.' => 'Отправьте ссылку кому угодно (Messenger, эл. почта). Зарегистрировавшиеся сразу появляются в протоколе.',
