    '✏️ Redaktoriai' => '✏️ Редакторы',
    'Žmonės, kurie gali patys keisti LTKF svetainę: tekstus, nuotraukas, failus, meniu, naujus puslapius. Kiekvienam - asmeninė nuoroda (paskyros nereikia, tik vardas). Išjungus nuorodą, redaguoti nebegalima.' => 'Люди, которые сами могут менять сайт LTKF: тексты, фото, файлы, меню, новые страницы. Каждому - личная ссылка (аккаунт не нужен, только имя). Если ссылку отключить, редактировать больше нельзя.',
