    'Vaikai ir kitų klubų nariai užsiregistruoja be paskyros: vardas, pavardė, gimimo data, telefonas. Iškart atsiranda šiame protokole ir gauna savo egzamino puslapį.' => 'Дети и члены других клубов регистрируются без аккаунта: имя, фамилия, дата рождения, телефон. Сразу появляются в этом протоколе и получают свою страницу экзамена.',
