    'Ką parašyti ChatGPT, kad pataisytų' => 'Что написать ChatGPT, чтобы исправил',
    'Jau esantys (tokiu pačiu tekstu) praleidžiami. Su [#numeriu] - pataisomi vietoje.' => 'Существующие (тот же текст) пропускаются. С [#номером] - исправляются на месте.',
    'Surinkta {a} XP (aktyvumo taškų). Iki {l} lygio - {n} XP.' => 'Собрано {a} XP (очков активности). До уровня {l} - {n} XP.',
    '🎁 Dovanų dėžė laukia Dojo.' => '🎁 В Додзё ждёт подарок.',
    'XP - aktyvumo taškai: už treniruotes, renginius, testus ir egzaminus' => 'XP - очки активности: за тренировки, мероприятия, тесты и экзамены',
    'iki {n} lygio: {xp} XP' => 'до уровня {n}: {xp} XP',
    'Pataisykite ir įkelkite atgal: Testai → šis testas → „Įkelti klausimus“.' => 'Исправьте и загрузите обратно: Тесты → этот тест → «Загрузить вопросы».',
    '[#123] - klausimo numeris: palikite jį, tada klausimas bus pataisytas, o ne pridėtas iš naujo. Naujiems klausimams numerio nereikia.' => '[#123] - номер вопроса: оставьте его, тогда вопрос будет исправлен, а не добавлен заново. Новым вопросам номер не нужен.',
    'Eilutės su // įkeliant praleidžiamos.' => 'Строки с // при загрузке пропускаются.',
    'Testuoja svetainę. Dojo ir žaidimo nemato, nustatymus mato tik skaityti.' => 'Тестирует сайт. Не видит Додзё и игру, настройки только для чтения.',
    '⭐ Lygis' => '⭐ Уровень',
    'Dar niekas nesurinko XP.' => 'Пока никто не набрал XP.',
