    'Dar niekas nelaimėjo - būk pirmas!' => 'Пока никто не победил - будь первым!',
    '🥁 Kata ritmas' => '🥁 Ритм ката',
    'Dar niekas nežaidė.' => 'Пока никто не играл.',
