    'Klausimas nerastas.' => 'Вопрос не найден.',
    'Atsakymas nerastas.' => 'Ответ не найден.',
    'Klausimo tekstas negali būti tuščias.' => 'Текст вопроса не может быть пустым.',
    'Tuščią atsakymą ištrinkite mygtuku 🗑.' => 'Пустой ответ удалите кнопкой 🗑.',
    'Daugiausia 4 atsakymai.' => 'Не более 4 ответов.',
    'Naujas atsakymas' => 'Новый ответ',
    'Klausimų peržiūra' => 'Просмотр вопросов',
    '← Atgal į testą' => '← Назад к тесту',
    '🔍 Klausimų peržiūra' => '🔍 Просмотр вопросов',
    'Eikite per klausimus. Jei viskas gerai - nieko nežymėkite, tiesiog „Toliau →“. ✕ - netinka (visas klausimas ar atsakymas), 💬 - komentaras. Tekstą galite taisyti iškart - išsaugoma savaime.' => 'Пройдите по вопросам. Если всё хорошо - ничего не отмечайте, просто «Далее →». ✕ - не подходит (весь вопрос или ответ), 💬 - комментарий. Текст можно сразу исправить - сохраняется само.',
    'Peržiūrėta' => 'Просмотрено',
    'su pastabomis' => 'с замечаниями',
