    'Kai baigsite' => 'Когда закончите',
    '⬇ Atsisiųsti pastabas ChatGPT' => '⬇ Скачать замечания для ChatGPT',
    '✓ Įtraukti į testą peržiūrėtus be pastabų' => '✓ Добавить в тест просмотренные без замечаний',
    'Atsisiųstą pastabų failą įkelkite ChatGPT (projekte „Karateka testai“) ir parašykite: „Pataisyk pagal pastabas“.' => 'Загрузите скачанный файл замечаний в ChatGPT (в проекте «Karateka testai») и напишите: «Исправь по замечаниям».',
    'ChatGPT atsakymą (failą ar tekstą) įkelkite: testas → „📥 Įkelti klausimus“ → „🔍 Įkelti peržiūrai“. Pataisyti klausimai vėl atsiras čia.' => 'Загрузите ответ ChatGPT (файл или текст): тест → «📥 Загрузить вопросы» → «🔍 Загрузить на просмотр». Исправленные вопросы снова появятся здесь.',
    'Peržiūrėti klausimai be pastabų įtraukiami į testą mygtuku aukščiau. Pastabų nebeliko - vadinasi, testas paruoštas.' => 'Просмотренные вопросы без замечаний добавляются в тест кнопкой выше. Замечаний не осталось - тест готов.',
    'Įtraukti į testą visus laukiančius klausimus, net ir neperžiūrėtus ar su pastabomis?' => 'Добавить в тест все ждущие вопросы, даже непросмотренные или с замечаниями?',
    'Įtraukti visus laukiančius' => 'Добавить все ждущие',
    'Išvalyti visas šio testo pastabas ir „peržiūrėta“ žymas?' => 'Удалить все замечания и отметки «просмотрено» этого теста?',
