    'Parašykite, už ką skiriate taškus.' => 'Напишите, за что начисляете баллы.',
    'Įkelta peržiūrai: {n}. Nariams jie dar nerodomi - peržiūrėkite ir patvirtinkite.' => 'Загружено на просмотр: {n}. Участники их пока не видят - просмотрите и подтвердите.',
    '🔍 Peržiūrėti klausimus' => '🔍 Просмотреть вопросы',
    'Peržiūros laukia klausimų:' => 'Вопросов ждут просмотра:',
    'Nariams jie dar nerodomi.' => 'Участники их пока не видят.',
    'reikės:' => 'нужно:',
    '🔍 Įkelti peržiūrai' => '🔍 Загрузить на просмотр',
    'Įkelti iš karto į testą' => 'Загрузить сразу в тест',
    '„Peržiūrai“ - nariams nerodomi, kol nepatvirtinsite. Jau esantys (tokiu pačiu tekstu) praleidžiami. Su [#numeriu] - pataisomi vietoje.' => '«На просмотр» - участники не видят, пока вы не подтвердите. Уже существующие (с тем же текстом) пропускаются. С [#номером] - исправляются на месте.',
    'arba pasirinkite failus' => 'или выберите файлы',
    '.txt, .csv, .json; galima kartu ir paveikslėlius (.png, .jpg) ar vieną ZIP su viskuo' => '.txt, .csv, .json; можно вместе с картинками (.png, .jpg) или один ZIP со всем',
    '🤖 ChatGPT nustatymas vieną kartą (kad visada ruoštų tinkamu formatu)' => '🤖 Однократная настройка ChatGPT (чтобы всегда готовил в нужном формате)',
    'ChatGPT kairėje: „Projects“ → „New project“ → pavadinkite „Karateka testai“.' => 'В ChatGPT слева: «Projects» → «New project» → назовите «Karateka testai».',
    'Projekte: „Instructions“ (Instrukcijos) → įklijuokite žemiau esantį tekstą → „Save“.' => 'В проекте: «Instructions» → вставьте текст ниже → «Save».',
    'Visus testų pokalbius pradėkite šiame projekte - formato kartoti nereikės.' => 'Начинайте все чаты о тестах в этом проекте - формат повторять не нужно.',
    'Kopijuoti nurodymus' => 'Копировать инструкции',
    'Dojo (žaidimas) kol kas paslėptas - meniu jo nemato niekas. Administratoriai jį gali išbandyti:' => 'Додзё (игра) пока скрыто - в меню его никто не видит. Администраторы могут попробовать:',
