    'Atsakymas {l} netinka - pakeisk jį kitu.' => 'Ответ {l} не подходит - замени его другим.',
    'Komentaras apie {l}:' => 'Комментарий к {l}:',
    'Visas klausimas netinka - parašyk naują vietoj jo (palik tą patį [#{id}]).' => 'Весь вопрос не подходит - напиши новый вместо него (оставь тот же [#{id}]).',
    'Komentaras:' => 'Комментарий:',
