    'ChatGPT: pataisyk tik šiuos klausimus pagal eilutes „>>“ (tai trenerio pastabos).' => 'ChatGPT: исправь только эти вопросы по строкам «>>» (это замечания тренера).',
    '✕ visas klausimas - parašyk naują ta pačia tema; ✕ atsakymas - pakeisk tą atsakymą; komentaras - atsižvelk.' => '✕ весь вопрос - напиши новый на ту же тему; ✕ ответ - замени этот ответ; комментарий - учти.',
