    'Administratorius savo paskyroje sukuria kodą: Valdymas → Nustatymai → Kodas kitam įrenginiui. Įveskite jį čia - šis įrenginys ribotą laiką galės tvarkyti svetainę ir varžybas.' => 'Администратор создаёт код в своём аккаунте: Valdymas → Настройки → Код для другого устройства. Введите его здесь - это устройство сможет ограниченное время управлять сайтом и соревнованиями.',
